'use strict';
// Runs after `tsc` (see the "build" script). Writes lib/vendor/jose-bundle.js,
// a CommonJS bundle of the jose exports the SDK uses (JOSE_EXPORTS). The SDK
// loads it only where require() cannot load jose's ES module build; see
// src/vendor/jose.ts. The output is deterministic: rebuilding with the same
// jose and esbuild versions produces the same bytes, so CI's built-files check
// catches a jose update that was not rebuilt.
const fs = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');

const root = path.resolve(__dirname, '..');
const vendorDir = path.join(root, 'lib', 'vendor');
const { JOSE_EXPORTS } = require(path.join(vendorDir, 'jose-exports.js'));
const joseDir = path.dirname(
  require.resolve('jose/package.json', { paths: [root] })
);
const jose = JSON.parse(
  fs.readFileSync(path.join(joseDir, 'package.json'), 'utf8')
);
const license = fs
  .readFileSync(path.join(joseDir, 'LICENSE.md'), 'utf8')
  .trim()
  .split(/\r?\n/);

const banner = [
  '/*!',
  ` * Bundled copy of jose@${jose.version} (${jose.homepage}).`,
  ' * Generated by scripts/bundle-jose.js. Do not edit.',
  ' *',
  ...license.map((line) => (line ? ` * ${line}` : ' *')),
  ' */',
].join('\n');

esbuild.buildSync({
  absWorkingDir: root,
  stdin: {
    contents: `export { ${JOSE_EXPORTS.join(', ')} } from 'jose';\n`,
    resolveDir: root,
    sourcefile: 'jose-bundle-entry.js',
    loader: 'js',
  },
  outfile: path.join(vendorDir, 'jose-bundle.js'),
  bundle: true,
  format: 'cjs',
  // jose's default export condition is its Web API build, which runs on
  // Node.js and on edge runtimes alike; neutral keeps esbuild from assuming
  // either.
  platform: 'neutral',
  target: 'es2022',
  minify: false,
  treeShaking: true,
  legalComments: 'inline',
  charset: 'ascii',
  banner: { js: banner },
  logLevel: 'warning',
});

// The loader's declaration file imports jose's types. Nothing public
// references it, so it is not shipped.
fs.rmSync(path.join(vendorDir, 'jose.d.ts'), { force: true });
